{"cards": [{"node_code": "N_a3ffec4930000030", "definition": "研究建设工程从立项、规划到施工全过程的法定程序，重点涵盖规划许可、施工许可的申请条件、审批流程及法律效力，确保工程活动符合行政监管要求。", "boundary": "本节点聚焦于工程启动前的行政审批与程序合规，包括建设用地规划许可、建设工程规划许可及施工许可证的办理。边界涵盖行政许可的法律依据、申请材料、审批时限及违规后果。不包含具体的结构设计、施工技术方案或项目内部的质量进度管理，这些属于技术或管理节点。", "includes": ["建设程序中的立项、用地及规划审批流程", "规划许可与施工许可的申请条件、审批程序及法律效力", "违反建设程序及许可制度的法律责任与行政处罚"], "excludes": ["具体的结构设计与力学计算（归入建筑与结构工程）", "具体的施工技术与工艺实施（归入工程施工与智能建造）", "项目内部的日常进度与质量控制（归入进度、质量与风险管理）"], "sibling_distinctions": [{"other_code": "N_9814436c82973fb7", "rule": "本节点关注具体的许可审批流程与程序合规；兄弟节点关注宏观的法律体系框架与基本制度原则。"}, {"other_code": "N_8fb14619d7b4a3d7", "rule": "本节点关注项目层面的行政许可（如施工证）；兄弟节点关注主体层面的资质与个人执业资格。"}], "cross_boundary_rule": "涉及许可审批程序及行政监管的归入本节点；涉及许可所依据的技术标准本身的技术原理归入相应技术节点。"}, {"node_code": "N_cdcda93ecc390c49", "definition": "研究工程安全与质量领域的强制性标准体系，明确各参建主体的法定安全责任、质量责任及违反强制性标准所导致的法律后果与责任追究机制。", "boundary": "本节点聚焦于安全质量领域的法律责任与合规性，包括强制性标准的法律地位、安全质量事故的法律责任界定及处罚。边界涵盖从设计、施工到验收全过程的安全质量法定义务。不包含具体的安全技术措施、质量检测技术或日常的质量控制流程，这些属于技术或管理节点。", "includes": ["工程安全与质量强制性标准的法律地位及执行要求", "各参建主体在安全质量方面的法定责任与义务", "安全质量事故的法律追责、行政处罚及民事赔偿责任"], "excludes": ["具体的结构安全计算与力学分析（归入建筑与结构工程）", "具体的施工安全技术措施与工艺（归入工程施工与智能建造）", "日常的质量控制流程与进度计划管理（归入进度、质量与风险管理）"], "sibling_distinctions": [{"other_code": "N_d3271166c41215aa", "rule": "本节点关注安全质量领域的具体责任界定与强制性标准合规；兄弟节点关注通用的诉讼仲裁程序及争议解决机制。"}, {"other_code": "N_a3ffec4930000030", "rule": "本节点关注实体安全质量标准的法律责任；兄弟节点关注程序性许可（如施工证）的行政合规。"}], "cross_boundary_rule": "涉及安全质量标准执行的法律后果归入本节点；涉及标准本身的技术原理归入相应技术节点。涉及安全质量事故的法律追责归入本节点；涉及事故后的具体技术鉴定归入检测技术节点。"}, {"node_code": "N_9f43425c04ff66fe", "definition": "研究工程勘察设计、监理及发承包环节的法律制度，明确各主体的法定权利、义务、责任及合同法律关系，规范工程市场交易行为与专业服务提供。", "boundary": "本节点聚焦于工程实施阶段各参与方之间的法律关系与制度规范，包括勘察设计合同、监理合同及施工发承包合同的法律性质与责任。边界涵盖从委托、签约到履约过程中的法律合规性。不包含具体的设计技术、监理技术方法或合同商务条款的拟定，这些属于技术或管理节点。", "includes": ["工程勘察设计、监理及发承包的法律制度与合同性质", "各参建主体在勘察设计、监理及发承包中的法定责任与义务", "违反勘察设计、监理及发承包法律规定的法律责任与争议处理"], "excludes": ["具体的结构设计与力学计算（归入建筑与结构工程）", "具体的监理技术方法与检测手段（归入检测技术或工程施工）", "合同商务条款的拟定与谈判（归入招标、采购与合同管理）"], "sibling_distinctions": [{"other_code": "N_8fb14619d7b4a3d7", "rule": "本节点关注合同关系中的法定责任与业务规范；兄弟节点关注主体进入市场前的资质与执业许可。"}, {"other_code": "N_d3271166c41215aa", "rule": "本节点关注特定业务环节（设计/监理/承包）的实体法律责任；兄弟节点关注通用的纠纷解决程序。"}], "cross_boundary_rule": "涉及合同履行的法律纠纷归入本节点；涉及合同商务条款的拟定与谈判归入招标、采购与合同管理。涉及监理法律地位与责任归入本节点；涉及监理具体技术操作归入检测技术或工程施工。"}]}
